macro_rules! IS_END {
    ($x:expr, $pEnd:expr) => {
        if !$pEnd.is_null() {
            (($x) == $pEnd) as i32
        } else {
            ((unsafe { *$x }) == 0) as i32
        }
    };
}

macro_rules! IS_SEP {
    ($x:expr) => {
        (unsafe { *$x }) == 47
    };
}

macro_rules! PyBytes_AS_STRING {
    ($op:expr) => {
        PyBytes_AS_STRING(_PyObject_CAST!($op))
    };
}

macro_rules! Py_ARRAY_LENGTH {
    () => {
        (core::mem::size_of::<[i32; 4097]>() as u64) / (core::mem::size_of::<i32>() as u64)
    };
}

macro_rules! Py_ARRAY_LENGTH__10 {
    () => {
        (core::mem::size_of::<[i8; 4096]>() as u64) / (core::mem::size_of::<i8>() as u64)
    };
}

macro_rules! Py_DECREF {
    ($op:expr) => {
        Py_DECREF(_PyObject_CAST!($op));
    };
}

/// Maximum value between x and y
macro_rules! Py_MAX {
    ($x:expr, $y:expr) => {
        if ($x) > $y { $x } else { $y }
    };
}

macro_rules! SEP_OR_END {
    ($x:expr, $pEnd:expr) => {
        IS_SEP!($x) || IS_END!($x, $pEnd) != 0
    };
}

