/// In-place path normalisation. Returns the start of the normalized
/// path, which will be within the original buffer. Guaranteed to not
/// make the path longer, and will not fail. 'size' is the length of
/// the path, if known. If -1, the first null character will be assumed
/// to be the end of the path.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_normpath(path: *mut i32, size: i64) -> *mut i32 {
    let mut norm_length: i64 = 0;
    _Py_normpath_and_size(path, size, core::ptr::addr_of_mut!(norm_length))
}

/// Get the current directory. buflen is the buffer size in wide characters
/// including the null character. Decode the path from the locale encoding.
///
/// Return NULL on getcwd() error, on decoding error, or if 'buf' is
/// too short.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_wgetcwd(buf: *mut i32, buflen: u64) -> *mut i32 {
    let mut fname: __SlateAlign16<[i8; 4096]> = __SlateAlign16([0i8; 4096]);
    let mut len: u64 = 0;
    if unsafe {
        getcwd(
            (fname.0.as_mut_ptr() as *mut i8) as *mut core::ffi::c_char,
            Py_ARRAY_LENGTH__10!() as usize,
        ) as *mut i8
    }
    .is_null()
    {
        return core::ptr::null_mut::<i32>();
    }
    let wname: *mut i32 = Py_DecodeLocale(
        fname.0.as_mut_ptr() as *const i8,
        core::ptr::addr_of_mut!(len),
    );
    if wname.is_null() {
        return core::ptr::null_mut::<i32>();
    }
    // wname must have space to store the trailing NUL character
    if buflen <= len {
        unsafe { PyMem_RawFree(wname as *mut ()) };
        return core::ptr::null_mut::<i32>();
    }
    unsafe { wcsncpy(buf, wname as *const i32, buflen) };
    unsafe { PyMem_RawFree(wname as *mut ()) };
    buf
}

/// Duplicate a file descriptor. The new file descriptor is created as
/// non-inheritable. Return a new file descriptor on success, raise an OSError
/// exception and return -1 on error.
///
/// The GIL is released to call dup(). The caller must hold the GIL.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_dup(mut fd: i32) -> i32 {
    let _save: *mut _ts = unsafe { PyEval_SaveThread() };
    fd = unsafe { fcntl(fd, slate_support::F_DUPFD_CLOEXEC as i32, 0i32) };
    unsafe { PyEval_RestoreThread(_save) };
    if fd < 0 {
        unsafe { PyErr_SetFromErrno(PyExc_OSError) };
        return 1i32.wrapping_neg();
    }
    fd
}

/// Get the blocking mode of the file descriptor.
/// Return 0 if the O_NONBLOCK flag is set, 1 if the flag is cleared,
/// raise an exception and return -1 on error.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_get_blocking(fd: i32) -> i32 {
    let flags: i32 = unsafe { fcntl(fd, slate_support::F_GETFL as i32, 0i32) };
    if flags < 0 {
        unsafe { PyErr_SetFromErrno(PyExc_OSError) };
        return 1i32.wrapping_neg();
    }
    (flags & (slate_support::O_NONBLOCK as i32) == 0) as i32
}

/// Set the blocking mode of the specified file descriptor.
///
/// Set the O_NONBLOCK flag if blocking is False, clear the O_NONBLOCK flag
/// otherwise.
///
/// Return 0 on success, raise an exception and return -1 on error.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_set_blocking(fd: i32, blocking: i32) -> i32 {
    // bpo-41462: On VxWorks, ioctl(FIONBIO) only works on sockets.
    // Use fcntl() instead.
    let mut arg: i32 = unsafe { core::mem::zeroed() };
    unsafe {
        arg = (blocking == 0) as i32;
        if (ioctl(fd as i32, 21537u64 as u64, core::ptr::addr_of_mut!(arg)) as i32) < 0 {
            PyErr_SetFromErrno(PyExc_OSError);
            return 1i32.wrapping_neg();
        } else {
            return 0;
        }
    }
}

#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_GetLocaleconvNumeric(
    lc: *mut slate_support::lconv,
    decimal_point: *mut *mut _object,
    thousands_sep: *mut *mut _object,
) -> i32 {
    let mut res: i32 = unsafe { core::mem::zeroed() };
    let mut loc: *mut i8 = unsafe { core::mem::zeroed() };
    // Keep a copy of the LC_CTYPE locale
    let mut oldloc: *mut i8 = unsafe { core::mem::zeroed() };
    let mut change_locale: i32 = unsafe { core::mem::zeroed() };
    unsafe {
        change_locale = 0;
        if (strlen(((*lc).decimal_point as *const i8) as *const core::ffi::c_char) as u64) > 1
            || ((*unsafe { (*lc).decimal_point }.wrapping_offset(0 as isize) as u8) as i32) > 127
        {
            change_locale = 1;
        }
        if (strlen(((*lc).thousands_sep as *const i8) as *const core::ffi::c_char) as u64) > 1
            || ((*unsafe { (*lc).thousands_sep }.wrapping_offset(0 as isize) as u8) as i32) > 127
        {
            change_locale = 1;
        }
        oldloc = core::ptr::null_mut::<i8>();
        loc = core::ptr::null_mut::<i8>();
        if change_locale != 0 {
            oldloc = setlocale(
                0i32 as i32,
                core::ptr::null::<i8>() as *const core::ffi::c_char,
            ) as *mut i8;
            if oldloc.is_null() {
                PyErr_SetString(
                    PyExc_RuntimeWarning,
                    c"failed to get LC_CTYPE locale".as_ptr(),
                );
                return 1i32.wrapping_neg();
            } else {
                oldloc = _PyMem_Strdup(oldloc as *const i8);
                if oldloc.is_null() {
                    PyErr_NoMemory();
                    return 1i32.wrapping_neg();
                } else {
                    loc = setlocale(
                        1i32 as i32,
                        core::ptr::null::<i8>() as *const core::ffi::c_char,
                    ) as *mut i8;
                    if !loc.is_null()
                        && (strcmp(
                            (loc as *const i8) as *const core::ffi::c_char,
                            (oldloc as *const i8) as *const core::ffi::c_char,
                        ) as i32)
                            == 0
                    {
                        loc = core::ptr::null_mut::<i8>();
                    }
                    if !loc.is_null() {
                        // Only set the locale temporarily the LC_CTYPE locale
                        // if LC_NUMERIC locale is different than LC_CTYPE locale and
                        // decimal_point and/or thousands_sep are non-ASCII or longer than
                        // 1 byte
                        setlocale(0i32 as i32, (loc as *const i8) as *const core::ffi::c_char)
                            as *mut i8;
                    }
                }
            }
        }
        res = 1i32.wrapping_neg();
        *decimal_point = GET_LOCALE_STRING!(decimal_point, lc);
        if !unsafe { *decimal_point }.is_null() {
            *thousands_sep = GET_LOCALE_STRING!(thousands_sep, lc);
            if !unsafe { *thousands_sep }.is_null() {
                res = 0;
            }
        }
        if !loc.is_null() {
            setlocale(
                0i32 as i32,
                (oldloc as *const i8) as *const core::ffi::c_char,
            ) as *mut i8;
        }
        PyMem_Free(oldloc as *mut ());
        return res;
    }
}

// Our selection logic for which function to use is as follows:
// 1. If close_range(2) is available, always prefer that; it's better for
//    contiguous ranges like this than fdwalk(3) which entails iterating over
//    the entire fd space and simply doing nothing for those outside the range.
// 2. If closefrom(2) is available, we'll attempt to use that next if we're
//    closing up to sysconf(_SC_OPEN_MAX).
// 2a. Fallback to fdwalk(3) if we're not closing up to sysconf(_SC_OPEN_MAX),
//    as that will be more performant if the range happens to have any chunk of
//    non-opened fd in the middle.
// 2b. If fdwalk(3) isn't available, just do a plain close(2) loop.
/// Closes all file descriptors in [first, last], ignoring errors.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_closerange(mut first: i32, last: i32) {
    first = Py_MAX!(first, 0i32);
    if (unsafe { close_range(first as u32, last as u32, 0i32) }) == 0 {
        // close_range() ignores errors when it closes file descriptors.
        // Possible reasons of an error return are lack of kernel support
        // or denial of the underlying syscall by a seccomp sandbox on Linux.
        // Fallback to other methods in case of any error.
    } else {
        if (last as i64) >= unsafe { sysconf((slate_support::_SC_OPEN_MAX as i32) as i32) as i64 } {
            // Any errors encountered while closing file descriptors are ignored
            unsafe { closefrom(first) };
        } else {
            let mut i: i32 = first;
            while i <= last {
                // Ignore errors
                unsafe { close(i as i32) as i32 };
                i = i.wrapping_add(1);
            }
        }
    }
}

/// Ticks per second used by clock() and times() functions.
///
/// See os.times() and time.process_time() implementations.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_GetTicksPerSecond(ticks_per_second: *mut i64) -> i32 {
    let value: i64 = unsafe { sysconf((slate_support::_SC_CLK_TCK as i32) as i32) as i64 };
    if value < 1 {
        return 1i32.wrapping_neg();
    }
    unsafe {
        *ticks_per_second = value;
    }
    0
}

/// Check if a file descriptor is valid or not.
/// Return 0 if the file descriptor is invalid, return non-zero otherwise.
#[unsafe(no_mangle)]
extern "C-unwind" fn _Py_IsValidFD(fd: i32) -> i32 {
    // dup() is faster than fstat(): fstat() can require input/output operations,
    // whereas dup() doesn't. There is a low risk of EMFILE/ENFILE at Python
    // startup. Problem: dup() doesn't check if the file descriptor is valid on
    // some platforms.
    //
    // fcntl(fd, F_GETFD) is even faster, because it only checks the process table.
    // It is preferred over dup() when available, since it cannot fail with the
    // "too many open files" error (EMFILE).
    //
    // bpo-30225: On macOS Tiger, when stdout is redirected to a pipe and the other
    // side of the pipe is closed, dup(1) succeed, whereas fstat(1, &st) fails with
    // EBADF. FreeBSD has similar issue (bpo-32849).
    //
    // Only use dup() on Linux where dup() is enough to detect invalid FD
    // (bpo-32849).
    if fd < 0 {
        return 0;
    }
    ((unsafe { fcntl(fd, slate_support::F_GETFD as i32) }) >= 0) as i32
}
